//! 🔗️ A qualified child retains the actual original registry payload through every funded issue/cancel cut.
use super::*;
use crate::child_view::{ChildContentEntry,editor::source::{ChildEditorFields,ChildEditorRequest,ChildEditorSourceCursor,ChildEditorSourceStep}};
use std::sync::Arc;
static EDITOR:ChildEditorCapability=ChildEditorCapability{artifact_kind:"s.fixture.child",standard:"1",subset:"*",editor_id:"s.fixture.child@1/*#editor",command_id:"edit"};
fn original()->RetainedCloneGrant{let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../🧭️source/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let g=&fixture["custodyGrant"];RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize}}
#[test]fn original_child_read_alias_and_source_issue_preserve_pointer_and_partial_refusals(){for cut in 0..=3{let grant=original();let registry=store::os_store::snapshot_read::SnapshotReadRegistryHandle::new();let payload=Arc::new(String::from("Original child Grüße 🌍"));let pointer=Arc::as_ptr(&payload);let lease=registry.try_issue(Arc::clone(&payload)).unwrap_or_else(|_|panic!("fixture original child issuer"));let entry=ChildContentEntry{owner:String::new(),slot:"backgroundDrawing".into(),child_id:"drawing-child".into(),artifact_id:"drawing-artifact".into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:EDITOR.artifact_kind.into(),standard:EDITOR.standard.into(),subset:EDITOR.subset.into()},revision:[42;32],snapshot:ErasedSnapshotRead::new(Arc::clone(&payload),lease)};let parent_revision=[31;32];let read=ChildEditorRead{read:entry.snapshot.typed::<String>().unwrap(),entry:&entry,parent_identity:22,parent_artifact:"layout",parent_revision:&parent_revision};let current=read.current(&EDITOR);let request=ChildEditorRequest{identity:11,expected_reference_identity:44,fields:ChildEditorFields{..current.fields}};let mut cursor=ChildEditorSourceCursor::new();let stamp=loop{if let ChildEditorSourceStep::Ready(stamp)=cursor.advance(&request,&current,grant).unwrap(){break stamp;}};let (address,paid)=semio_framework_io_ports::ChildAdmissionAddress::admit(7,&stamp,grant).unwrap();assert!(paid.fits(grant));assert_eq!(address.ordinal(),7);assert!(address.matches(&stamp));let mut owner=ChildEditorSourceCustody::new();
 for turn in 0..cut{let demand=owner.next_admit_demand().unwrap();let mut denied=vec![RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant}];if demand.copy_bytes>0{denied.push(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..grant});}if demand.capacity_bytes>0{denied.push(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes-1,..grant});}for denied in denied{let count=Arc::strong_count(&payload);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||read.admit_original_source(&EDITOR,&stamp,&mut owner,denied));assert_eq!(result.unwrap().progress(),Default::default());assert_eq!(Arc::strong_count(&payload),count);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||read.admit_original_source(&EDITOR,&stamp,&mut owner,grant));let p=result.unwrap().progress();assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));if turn>=1{assert!(owner.ready());assert_eq!(owner.source().unwrap().get()as*const String,pointer);let loan=semio_framework_io_ports::project_child_admission_source::<String>(owner.opaque_source().unwrap(),1).unwrap();assert_eq!(loan.get()as*const String,pointer);}}
 owner.begin_close();assert!(owner.source().is_err());let mut close=owner.into_retirement().unwrap_or_else(|_|panic!("native child source has controlled original retirement"));for _ in 0..10000{if close.terminal_is_empty(){break;}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||close.step(grant));let p=result.unwrap().progress();assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}assert!(close.terminal_is_empty());cursor.cancel();assert!(cursor.close_one(grant));drop(read);let root=match entry.snapshot.into_typed::<String>(&registry){Ok(root)=>root,Err(_)=>panic!("original member root returns to its same registry")};assert_eq!(Arc::as_ptr(&root),pointer);drop(root);assert!(registry.terminal_is_empty());drop(payload);let mut registry=Some(store::os_store::snapshot_read::SnapshotReadRegistryAliasRetirement::new(registry));for _ in 0..10000{if registry.is_none(){break;}store::os_store::snapshot_read::snapshot_registry_alias_close_step(&mut registry,grant).unwrap();}assert!(registry.is_none());}}
